select c.customername, count(distinct o.ordernumber) as total_pesanan, round(avg(od.quantityordered ), 2) as avg_quantity_per_order from customers c join orders o on o.customernumber = c.customernumber join orderdetails od on o.ordernumber = od.ordernumber group by c.customername having count(distinct o.ordernumber) > 3 and round(avg(od.quantityordered ), 2) > 35 order by total_pesanan desc, avg_quantity_per_order desc
